//! ShipStruts.java's exact shared geometry shader.
pub(crate) const SOURCE: &str = "\n    #version 150 core\n\n    layout(lines) in;\n    layout(line_strip, max_vertices = 2) out;\n\n    out vec2 vTexCoord;\n\n    uniform mat4 transform;\n    uniform vec2 resolution;\n    uniform vec2 u_mouse;\n\n    uniform sampler2D pos;\n    uniform usampler2D valueMask;\n\n    void main()\n    {\n        ivec2 i[2] = ivec2[2](\n            ivec2(gl_in[0].gl_Position.xy),\n            ivec2(gl_in[1].gl_Position.xy)\n        );\n        ivec2 diff = i[1] - i[0];\n\n        vec2 off[2] = vec2[2](\n            (vec2(i[0])+ vec2(0.5)) / (resolution) ,\n            (vec2(i[1]) + vec2(0.5)) / (resolution)\n        );\n\n        uvec3 dat[2] = uvec3[2](\n            texelFetch(valueMask, i[0], 0).xyz,\n            texelFetch(valueMask, i[1], 0).xyz\n        );\n\n        vec4 position[2] = vec4[2](\n            transform * vec4(texelFetch(pos, i[0], 0).xy + u_mouse, 0, 1),\n            transform * vec4(texelFetch(pos, i[1], 0).xy + u_mouse, 0, 1)\n        );\n\n        uint bit;\n        if (diff.x == 1) {\n            bit = uint(diff.y);\n        } else {\n            bit = 2u + uint(-diff.x);\n        }\n        if ((dat[0].y & (1u << bit)) != 0u) {\n            vTexCoord = off[0];\n            gl_Position = position[0];\n            EmitVertex();\n\n            vTexCoord = off[1];\n            gl_Position = position[1];\n            EmitVertex();\n            EndPrimitive();\n        }\n    }\n";
